# Let me look for repeated patterns and simpler rules
inputs = ['duzu', 'kdciaw', 'cdwhw', 'zgku', 'ukfd']
outputs = ['duzu', 'veedciaivee', 'cdiveehivee', 'zgveeu', 'uveeabd']

print("Looking for simple patterns:")
print("=" * 40)

# Check for single character replacements
patterns = {}
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    if inp != out:
        print(f"'{inp}' -> '{out}'")
        # Let's see what we can extract
        for j in range(len(inp)):
            if j < len(out):
                if inp[j] != out[j]:
                    print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        print()

# Check for two-character patterns  
print("Checking for two-character patterns:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    if inp != out:
        print(f"'{inp}' -> '{out}'")
        # Check all possible substrings
        for length in range(2, min(4, len(inp)+1)):
            for start in range(len(inp) - length + 1):
                sub = inp[start:start+length]
                # Find where this appears in output
                pos = out.find(sub)
                if pos != -1:
                    print(f"  Found '{sub}' at position {start} in input, matches at position {pos} in output")
        print()

